SELECT s1.`c0` AS `x` FROM (SELECT s2.`c0` AS `c0` FROM (SELECT s3.`c0` AS `c0` FROM (SELECT v.`c0` AS `c0` FROM (VALUES (CAST(1 AS BIGINT)), (CAST(2 AS BIGINT))) AS v(`c0`)) AS s3 UNION ALL SELECT s4.`c0` AS `c0` FROM (SELECT v.`c0` AS `c0` FROM (VALUES (CAST(3 AS BIGINT)), (CAST(4 AS BIGINT))) AS v(`c0`)) AS s4) AS s2 LIMIT 2 OFFSET 1) AS s1
